string dir="Assets/BlightBloom/Art/Interiors/CrookedMortar/ShopWorkflow10/",source="ArtSource/Blender/Interiors/CrookedMortar/ShopWorkflow10/";var sc=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var room=GameObject.Find("22 ShopWorkflow10 - isolated artistic reconstruction");var originals=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>!r.transform.IsChildOf(room.transform)).ToArray();var disabled=new System.Collections.Generic.List<Renderer>();
