int skins=0;void Skin(Renderer r,Vector3 inward,string n,bool ceiling=false){var mf=r.GetComponent<MeshFilter>();if(mf==null)return;var mesh=mf.sharedMesh;var v=mesh.vertices;var triangles=mesh.triangles;var vertices=new System.Collections.Generic.List<Vector3>();var uv=new System.Collections.Generic.List<Vector2>();for(int i=0;i<triangles.Length;i+=3){var a=r.transform.TransformPoint(v[triangles[i]]);var b=r.transform.TransformPoint(v[triangles[i+1]]);var c=r.transform.TransformPoint(v[triangles[i+2]]);var normal=Vector3.Cross(b-a,c-a).normalized;var mid=(a+b+c)/3;if(Vector3.Dot(normal,inward)<.90f||mid.y<.2f||mid.y>3.31f)continue;if(mid.x<-.21f||mid.x>5.61f||mid.z<-.01f||mid.z>4.61f)continue;foreach(var p0 in new[]{a,b,c}){var p=p0+inward*.002f;if(ceiling){p.x=Mathf.Clamp(p.x,0,5.4f);p.z=Mathf.Clamp(p.z,0,4.4f);}vertices.Add(p);float along=Mathf.Abs(inward.x)>.5f?p.z:p.x;uv.Add(ceiling?new Vector2(p.x/.8f,p.z/2.5f):new Vector2(.025f+Mathf.Clamp01(along/5.6f)*.44f,.025f+Mathf.Clamp01((p.y-.2f)/3.1f)*.95f));}}
if(vertices.Count==0)return;var m=new Mesh{name=n};m.SetVertices(vertices);m.SetUVs(0,uv);m.triangles=Enumerable.Range(0,vertices.Count).ToArray();m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,dir+"FittedMeshes/"+n+".asset");var go=new GameObject(n);go.transform.SetParent(room.transform,false);go.AddComponent<MeshFilter>().sharedMesh=m;go.AddComponent<MeshRenderer>().sharedMaterial=mats[ceiling?"CM_SW10_CeilingWalnut":"CM_SW10_PaintedPlaster"];go.layer=2;skins++;}
foreach(var r in originals){string n=r.name;if(n.StartsWith("Front entrance 2.0 jamb")||n=="Front entrance 2.0 lintel 2.75m clear")Skin(r,Vector3.forward,"CM_SW10_Inside_"+n.Replace(' ','_'));else if(n.StartsWith("Shop to kitchen"))Skin(r,Vector3.left,"CM_SW10_Inside_"+n.Replace(' ','_'));else if(n.StartsWith("Shop to treatment"))Skin(r,Vector3.back,"CM_SW10_Inside_"+n.Replace(' ','_'));else if(n=="West shop front")Skin(r,Vector3.right,"CM_SW10_InsideWest");else if(n=="Upper living and open landing")Skin(r,Vector3.down,"CM_SW10_Ceiling",true);}
